create or replace view catalog.machine_products with (security_invoker=true) as select p.id,p.public_id,p.slug,p.name_ar,p.name_en,p.description_ar,p.description_en,p.product_type,v.id variant_id,v.sku,v.name_ar variant_name_ar,v.name_en variant_name_en,v.attributes,pr.amount,pr.currency,coalesce(sum(i.on_hand-i.reserved),0) available_stock from catalog.products p join catalog.product_variants v on v.product_id=p.id left join catalog.prices pr on pr.product_variant_id=v.id and pr.is_active=true and pr.currency='EGP' left join inventory.items i on i.product_variant_id=v.id where p.status='active' and v.status='active' group by p.id,v.id,pr.amount,pr.currency;grant select on catalog.machine_products to anon,authenticated;